function addBinary(a: string, b: string): string {
  // Складываем «столбиком» с младших разрядов (с конца строк)
  let i = a.length - 1;
  let j = b.length - 1;
  let carry = 0;
  const bits: number[] = [];

  // Продолжаем, пока остались разряды хотя бы в одной строке или есть перенос
  while (i >= 0 || j >= 0 || carry > 0) {
    // Отсутствующий разряд считаем нулём
    const x = i >= 0 ? a.charCodeAt(i) - 48 : 0; // 48 — код символа '0'
    const y = j >= 0 ? b.charCodeAt(j) - 48 : 0;

    const sum = x + y + carry; // от 0 до 3
    bits.push(sum & 1); // младший бит суммы — цифра текущего разряда
    carry = sum >> 1; // старший бит — перенос в следующий разряд

    i--;
    j--;
  }

  // Цифры собраны от младших к старшим — разворачиваем
  return bits.reverse().join('');
}

// Время: O(max(|a|, |b|))
// Память: O(max(|a|, |b|)) — под результат
